package net.civeira.phylax.feature.identity.user.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.user.domain.User;
import net.civeira.phylax.feature.identity.user.domain.valueobject.UseSecondFactorsVO;

class UseSecondFactorsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of use second factors of user")
  void test_use_second_factors_value_holder_assign_plain_value() {
    Object holder = new Object();
    UseSecondFactorsValueHolder<Object> value = new UseSecondFactorsValueHolder<>(holder);
    Assertions.assertSame(holder, value.useSecondFactors(true), "Setters must return the holder");
    Assertions.assertTrue(value.getUseSecondFactorsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getUseSecondFactors().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.useSecondFactorsNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getUseSecondFactorsValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of use second factors of user")
  void test_use_second_factors_value_holder_assign_value_object() {
    Object holder = new Object();
    UseSecondFactorsValueHolder<Object> value = new UseSecondFactorsValueHolder<>(holder);
    UseSecondFactorsVO vo = UseSecondFactorsVO.from(true);
    Assertions.assertFalse(value.getUseSecondFactorsValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.useSecondFactors(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getUseSecondFactorsValue().orElseThrow());
    Assertions.assertSame(holder, value.useSecondFactors(Optional.empty()));
    Assertions.assertFalse(value.getUseSecondFactorsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.useSecondFactors(Optional.of(vo)));
    Assertions.assertSame(vo, value.getUseSecondFactorsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of use second factors of user against the original")
  void test_use_second_factors_value_holder_read() {
    Object holder = new Object();
    UseSecondFactorsValueHolder<Object> value = new UseSecondFactorsValueHolder<>(holder);
    UseSecondFactorsVO vo = UseSecondFactorsVO.from(true);
    UseSecondFactorsVO other = UseSecondFactorsVO.from(true);
    User original = Mockito.mock(User.class);
    Mockito.when(original.getUseSecondFactorsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readUseSecondFactors(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readUseSecondFactors(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.useSecondFactors(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readUseSecondFactors(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readUseSecondFactors(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of use second factors of user")
  void test_use_second_factors_value_holder_unset() {
    Object holder = new Object();
    UseSecondFactorsValueHolder<Object> value = new UseSecondFactorsValueHolder<>(holder);
    UseSecondFactorsVO vo = UseSecondFactorsVO.from(true);
    value.useSecondFactors(vo);
    Assertions.assertSame(holder, value.unsetUseSecondFactorsIfMatches("useSecondFactors_other"));
    Assertions.assertTrue(value.getUseSecondFactorsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetUseSecondFactorsIfMatches("useSecondFactors"));
    Assertions.assertFalse(value.getUseSecondFactorsValue().isPresent(),
        "The field name must clear the value");
    value.useSecondFactors(vo);
    Assertions.assertSame(holder, value.unsetUseSecondFactors());
    Assertions.assertFalse(value.getUseSecondFactorsValue().isPresent(),
        "Unset must clear the value");
  }
}
